(function() {
    'use strict';

    class HubLegalFormAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The Hub: Founding Day';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 4000,
                    deadlineDays: 28,
                    alignmentScore: 0,
                    insightScore: 0,
                    totalScore: 0,
                    scoreHistory: [],
                    chosenForm: null,
                    mayaAxis: null,
                    danielAxis: null,
                    aishaAxis: null,
                    scenarioAForm: null,
                    scenarioBForm: null,
                    scenarioCForm: null
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    mayaAxis: 'setup_cost',
                    danielAxis: 'liability',
                    aishaAxis: 'continuity',
                    scenarioAForm: 'limited_company',
                    scenarioBForm: 'limited_company',
                    scenarioCForm: 'limited_company',
                    finalForm: 'limited_company',
                    primaryAxis: 'liability'
                };
            }
            var self = this;
            self._updateBriefing(window.mySimulation.state);
        }

        validateDecisions(decisions) {
            var period = (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state.currentPeriod : 1;
            /* v1.1.0: removed validate-time DOM write (validation is now side-effect free; panel refreshes on period:submitted). */
if (period === 1) {
                var maya = document.getElementById('mayaAxisInput');
                var daniel = document.getElementById('danielAxisInput');
                var aisha = document.getElementById('aishaAxisInput');
                if (maya) decisions.mayaAxis = maya.value;
                if (daniel) decisions.danielAxis = daniel.value;
                if (aisha) decisions.aishaAxis = aisha.value;
                if (!decisions.mayaAxis || !decisions.danielAxis || !decisions.aishaAxis) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warning_round1'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var sa = document.getElementById('scenarioAInput');
                var sb = document.getElementById('scenarioBInput');
                var sc = document.getElementById('scenarioCInput');
                if (sa) decisions.scenarioAForm = sa.value;
                if (sb) decisions.scenarioBForm = sb.value;
                if (sc) decisions.scenarioCForm = sc.value;
                if (!decisions.scenarioAForm || !decisions.scenarioBForm || !decisions.scenarioCForm) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warning_round2'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var ff = document.getElementById('finalFormInput');
                var pa = document.getElementById('primaryAxisInput');
                if (ff) decisions.finalForm = ff.value;
                if (pa) decisions.primaryAxis = pa.value;
                if (!decisions.finalForm || !decisions.primaryAxis) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warning_round3'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var d = state.decisions;
            var alignmentScore = 0;
            var insightScore = 0;
            var feedback = '';

            if (period === 1) {
                if (d.mayaAxis === 'setup_cost') alignmentScore += 5;
                if (d.danielAxis === 'liability') alignmentScore += 5;
                if (d.aishaAxis === 'continuity') alignmentScore += 5;

                state.domainState.mayaAxis = d.mayaAxis;
                state.domainState.danielAxis = d.danielAxis;
                state.domainState.aishaAxis = d.aishaAxis;

                if (alignmentScore === 15) {
                    feedback = window.mySimulation.t('feedback_r1_perfect');
                    insightScore = 5;
                } else if (alignmentScore >= 10) {
                    feedback = window.mySimulation.t('feedback_r1_good');
                    insightScore = 3;
                } else {
                    feedback = window.mySimulation.t('feedback_r1_partial');
                    insightScore = 1;
                }
            } else if (period === 2) {
                var greenA = ['limited_company', 'cooperative', 'social_enterprise'];
                var greenB = ['limited_company', 'cooperative', 'social_enterprise'];
                var greenC = ['limited_company', 'social_enterprise'];

                if (greenA.indexOf(d.scenarioAForm) !== -1) alignmentScore += 5;
                if (greenB.indexOf(d.scenarioBForm) !== -1) alignmentScore += 5;
                if (greenC.indexOf(d.scenarioCForm) !== -1) alignmentScore += 5;

                state.domainState.scenarioAForm = d.scenarioAForm;
                state.domainState.scenarioBForm = d.scenarioBForm;
                state.domainState.scenarioCForm = d.scenarioCForm;

                if (alignmentScore === 15) {
                    feedback = window.mySimulation.t('feedback_r2_perfect');
                    insightScore = 5;
                } else if (alignmentScore >= 10) {
                    feedback = window.mySimulation.t('feedback_r2_good');
                    insightScore = 3;
                } else {
                    feedback = window.mySimulation.t('feedback_r2_partial');
                    insightScore = 1;
                }
            } else if (period === 3) {
                state.domainState.chosenForm = d.finalForm;

                var coherent = false;
                var liabilityForms = ['limited_company', 'cooperative', 'social_enterprise'];
                var setupCheapForms = ['sole_trader', 'partnership'];
                var continuityForms = ['limited_company', 'cooperative', 'social_enterprise'];
                var capitalForms = ['limited_company'];
                var controlForms = ['sole_trader'];
                var profitForms = ['sole_trader', 'limited_company', 'partnership'];

                if (d.primaryAxis === 'liability' && liabilityForms.indexOf(d.finalForm) !== -1) coherent = true;
                if (d.primaryAxis === 'setup_cost' && setupCheapForms.indexOf(d.finalForm) !== -1) coherent = true;
                if (d.primaryAxis === 'continuity' && continuityForms.indexOf(d.finalForm) !== -1) coherent = true;
                if (d.primaryAxis === 'capital' && capitalForms.indexOf(d.finalForm) !== -1) coherent = true;
                if (d.primaryAxis === 'control' && controlForms.indexOf(d.finalForm) !== -1) coherent = true;
                if (d.primaryAxis === 'profit_distribution' && profitForms.indexOf(d.finalForm) !== -1) coherent = true;

                if (coherent) {
                    alignmentScore = 15;
                    insightScore = 10;
                    feedback = window.mySimulation.t('feedback_r3_coherent') +
                        '<br>' + this._getCounterArgument(d.finalForm);
                } else {
                    alignmentScore = 5;
                    insightScore = 3;
                    feedback = window.mySimulation.t('feedback_r3_incoherent') +
                        '<br>' + this._getCounterArgument(d.finalForm);
                }
            }

            state.domainState.alignmentScore += alignmentScore;
            state.domainState.insightScore += insightScore;
            state.domainState.totalScore = state.domainState.alignmentScore + state.domainState.insightScore;
            state.domainState.scoreHistory.push(alignmentScore + insightScore);

            var self = this;
            /* v1.1.0: removed racy setTimeout N+2 desync; panel refreshes on the real period:submitted / period:undone events wired in setupUI. */

            return {
                period: period,
                alignmentScore: alignmentScore,
                insightScore: insightScore,
                roundScore: alignmentScore + insightScore,
                feedback: feedback,
                totalScore: state.domainState.totalScore
            };
        }

        _getCounterArgument(form) {
            var key = 'counter_' + form;
            return window.mySimulation.t(key);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '€' + Math.round(v).toLocaleString());
            uiManager.bind('deadlineDisplay', 'domainState.deadlineDays',
                (v) => v + ' days');
            uiManager.bind('alignmentScoreDisplay', 'domainState.alignmentScore');
            uiManager.bind('insightScoreDisplay', 'domainState.insightScore');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore');
            uiManager.bind('roundScoreDisplay', 'results.roundScore');
            uiManager.bind('feedbackDisplay', 'results.feedback');


            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); } catch (e) {} };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                this._wired = true;
            }
        }

        getChartConfig() {
            return {
                progressChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Score',
                            data: [],
                            backgroundColor: 'rgba(212, 165, 116, 0.7)',
                            borderColor: '#6f4e37',
                            borderWidth: 2,
                            borderRadius: 6
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: {
                                display: true,
                                text: 'Score by Round',
                                color: '#4a3527',
                                font: { size: 14, weight: '700' }
                            },
                            legend: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 25,
                                ticks: { color: '#6f5a45' },
                                grid: { color: 'rgba(111, 78, 55, 0.08)' }
                            },
                            x: {
                                ticks: { color: '#6f5a45' },
                                grid: { display: false }
                            }
