        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) {
                return 'R' + (i + 1);
            });
            return {
                progressChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = history.reduce(function(s, r) {
                return s + ((r.results && r.results.roundScore) || 0);
            }, 0);

            var performance = 'Beginner';
            if (totalScore >= 60) performance = 'Excellent';
            else if (totalScore >= 40) performance = 'Good';
            else if (totalScore >= 25) performance = 'Developing';

            var insights = [];
            insights.push('You scored ' + totalScore + ' out of 75 across the three rounds.');
            insights.push('Remember: the right legal form depends on which axis matters most to your founders.');
            insights.push('Sim 1232 will revisit The Hub accounts — your choice today shapes what those accounts must look like.');

            return {
                totalScore: totalScore,
                performance: performance,
                insights: insights
            };
        }

